import{_ as a,o as s,c as t,a5 as n}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{"title":"Frequently asked questions","docId":"user.preferences.faq","translationKey":"user.preferences.faq","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","translationRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","order":40},"headers":[],"relativePath":"en/user/preferences/faq.md","filePath":"en/user/preferences/faq.md","lastUpdated":1794591482000}'),r={name:"en/user/preferences/faq.md"};function i(o,e,d,l,c,h){return s(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions {#frequently-asked-questions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Resolve common workflow confusion before changing data or credentials. You need the running desktop app for the checks below; <a href="./../requirements.html">requirements</a> describes supported packages. The local features discussed here are available unless an experimental or service-dependent limit is stated.</p><h2 id="does-cloud-sign-in-connect-tiktok" tabindex="-1">Does Cloud sign-in connect TikTok? <a class="header-anchor" href="#does-cloud-sign-in-connect-tiktok" aria-label="Permalink to &quot;Does Cloud sign-in connect TikTok? {#does-cloud-sign-in-connect-tiktok}&quot;">​</a></h2><p>No. Open <a href="./../live/connections.html">Connections</a>, choose a creator and start LIVE separately. Cloud identity supports account-based services. A TikTok cookie belongs only in its intended masked connection field.</p><h2 id="why-is-a-connected-feed-empty" tabindex="-1">Why is a connected feed empty? <a class="header-anchor" href="#why-is-a-connected-feed-empty" aria-label="Permalink to &quot;Why is a connected feed empty? {#why-is-a-connected-feed-empty}&quot;">​</a></h2><p>A quiet room may have no new events. Choose all events, clear search and resume scrolling, then inspect connection status. Pausing scrolling leaves ingestion and automations running. Clearing the feed does not reset points or persisted analytics.</p><h2 id="are-statistics-only-for-this-session" tabindex="-1">Are statistics only for this session? <a class="header-anchor" href="#are-statistics-only-for-this-session" aria-label="Permalink to &quot;Are statistics only for this session? {#are-statistics-only-for-this-session}&quot;">​</a></h2><p>The current <a href="./../points/statistics.html">Analytics page</a> queries persisted aggregates for the selected creator and date range. Widen the dates and refresh to inspect recorded history. It is not a complete chat transcript. Point balances use different rules and can include manual or automation adjustments.</p><h2 id="where-are-templates-variables-and-rankings" tabindex="-1">Where are templates, variables and rankings? <a class="header-anchor" href="#where-are-templates-variables-and-rankings" aria-label="Permalink to &quot;Where are templates, variables and rankings? {#where-are-templates-variables-and-rankings}&quot;">​</a></h2><p>Templates and profiles live in <a href="./../automations/templates.html">Automations</a>; Plugins Explore requests plugins. Runtime values live in Automations Variables. The experimental Rankings workspace still has <code>#/rankings</code>, but is hidden from main navigation and startup restoration. Ordinary point leaderboards and feed ranking panels remain separate views.</p><h2 id="does-saving-synchronize-everything" tabindex="-1">Does saving synchronize everything? <a class="header-anchor" href="#does-saving-synchronize-everything" aria-label="Permalink to &quot;Does saving synchronize everything? {#does-saving-synchronize-everything}&quot;">​</a></h2><p>No. Events/Actions Changes compares a local reference. Variables saving stays local, with separate reviewed send/adopt/withdraw operations when supported. Secret comparisons are masked. Cloud overlays use create/revise and library operations; this version has no shared overlay Changes adapter. Read <a href="./../cloud/changes.html">Changes</a> before choosing a direction.</p><h2 id="are-tests-harmless-and-do-imports-run-immediately" tabindex="-1">Are tests harmless, and do imports run immediately? <a class="header-anchor" href="#are-tests-harmless-and-do-imports-run-immediately" aria-label="Permalink to &quot;Are tests harmless, and do imports run immediately? {#are-tests-harmless-and-do-imports-run-immediately}&quot;">​</a></h2><p>Tests can execute effects, including audio, network requests and point changes. Begin with <a href="./../automations/first-rule.html">core.log</a>. Imported definitions remain disabled; review and explicitly activate them. Installing a plugin also requires its service configuration before its actions can work.</p><h2 id="expected-result-and-recovery" tabindex="-1">Expected result and recovery <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Expected result and recovery {#expected-result-and-recovery}&quot;">​</a></h2><p>These checks should identify the responsible page without a reset. Automatic update checks are optional; installation is experimental and disabled by current release gates. Full remote collaboration and production nickname search still depend on deployment and acceptance. If uncertainty remains, preserve your data through <a href="./backups.html">backups</a> and collect a <a href="./troubleshooting.html">diagnostic report</a> with version, time and reproduction.</p>',17)])])}const m=a(r,[["render",i]]);export{p as __pageData,m as default};
